// File: p2p-kids-marketplace/src/screens/LoginScreen.tsx
// MODULE-03 AUTH-V2-003: Login with Subscription Context

import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { loginWithContext } from '@/services/auth';
import { AuthError } from '@/types/user';
import { useAuth } from '@/hooks/useAuth';
import { AuthSession } from '@/types/user';

type NavigationProp = NativeStackNavigationProp<any>;

// Default export for existing navigation
export default function LoginScreen() {
  const { setSession } = useAuth();
  const navigation = useNavigation<NavigationProp>();

  const handleDevSkipAuth = () => {
    const now = new Date().toISOString();
    const mockSession: AuthSession = {
      user: {
        id: '00000000-0000-0000-0000-000000000002',
        user_id: '00000000-0000-0000-0000-000000000001',
        email: 'dev.maestro@example.com',
        name: 'Dev Maestro User',
        display_name: 'Dev Maestro User',
        profile_completed: true,
        onboarding_completed: true,
        onboarding_completed_at: now,
        phone_verified: true,
        parental_consent_verified: true,
        created_at: now,
        updated_at: now,
      },
      subscription_status: 'free',
      can_spend_sp: false,
      available_points: 0,
      pending_points: 0,
      lifetime_earned: 0,
      lifetime_spent: 0,
      wallet_state: 'inactive', // ADMIN-V2-003
    };

    setSession(mockSession);
  };

  // Form state
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // UI state
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  /**
   * Validate form inputs
   */
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(email)) {
      newErrors.email = 'Email is invalid';
    }

    if (!password) {
      newErrors.password = 'Password is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  /**
   * Handle login submission
   */
  const handleLogin = async () => {
    if (!validateForm()) {
      return;
    }

    setLoading(true);
    setErrors({});

    try {
      const session = await loginWithContext({
        email: email.trim(),
        password,
      });

      // Success - update auth context which triggers automatic navigation
      // Session context includes subscription status and SP balance
      console.log('Login successful:', {
        user: session.user.name,
        subscription: session.subscription_status,
        availablePoints: session.available_points,
      });

      // Update auth context - this triggers automatic navigation to Home via RootNavigator
      setSession(session);
    } catch (error: any) {
      console.error('Login error:', error);

      let errorMessage = 'Login failed. Please check your credentials.';

      if (error instanceof AuthError) {
        switch (error.code) {
          case 'INVALID_CREDENTIALS':
          case 'LOGIN_FAILED':
            errorMessage = 'Invalid email or password.';
            break;
          case 'PROFILE_NOT_FOUND':
            errorMessage = 'Profile not found. Please contact support.';
            break;
          case 'ACCOUNT_DELETED':
            errorMessage =
              'Your account has been deleted. Please contact admin-support@kidsmarketplace.app.';
            break;
          default:
            errorMessage = error.message;
        }
      }

      Alert.alert('Login Failed', errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <View style={styles.content}>
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.title}>Welcome Back!</Text>
          <Text style={styles.subtitle}>Log in to continue trading and earning Swap Points</Text>
        </View>

        {/* Form */}
        <View style={styles.form}>
          {/* Email */}
          <View style={styles.inputGroup}>
            <Text style={styles.label}>Email</Text>
            <TextInput
              style={[styles.input, errors.email && styles.inputError]}
              placeholder="your.email@example.com"
              placeholderTextColor="#6B7280"
              value={email}
              testID="login-email-input"
              onChangeText={setEmail}
              autoCapitalize="none"
              keyboardType="email-address"
              autoComplete="email"
              editable={!loading}
            />
            {errors.email && <Text style={styles.errorText}>{errors.email}</Text>}
          </View>

          {/* Password */}
          <View style={styles.inputGroup}>
            <Text style={styles.label}>Password</Text>
            <TextInput
              style={[styles.input, errors.password && styles.inputError]}
              placeholder="Enter your password"
              placeholderTextColor="#6B7280"
              value={password}
              testID="login-password-input"
              onChangeText={setPassword}
              secureTextEntry
              autoCapitalize="none"
              autoComplete="password"
              editable={!loading}
            />
            {errors.password && <Text style={styles.errorText}>{errors.password}</Text>}
          </View>

          {/* Login Button */}
          <TouchableOpacity
            style={[styles.button, loading && styles.buttonDisabled]}
            onPress={handleLogin}
            testID="login-submit-button"
            disabled={loading}
          >
            {loading ? (
              <ActivityIndicator color="#fff" />
            ) : (
              <Text style={styles.buttonText}>Log In</Text>
            )}
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.devSkipButton}
            onPress={handleDevSkipAuth}
            testID="login-skip-auth-button"
            disabled={loading}
          >
            <Text style={styles.devSkipButtonText}>Skip Auth (Test)</Text>
          </TouchableOpacity>

          {/* Signup Link */}
          <View style={styles.footer}>
            <Text style={styles.footerText}>Don't have an account? </Text>
            <TouchableOpacity
              onPress={() => navigation.navigate('Signup')}
              testID="login-signup-link"
              disabled={loading}
            >
              <Text style={styles.linkText}>Sign Up</Text>
            </TouchableOpacity>
          </View>

          {/* Forgot Password Link */}
          <TouchableOpacity
            style={styles.forgotPassword}
            onPress={() => {
              // TODO: Navigate to forgot password screen
              Alert.alert('Forgot Password', 'Feature coming soon!');
            }}
            disabled={loading}
          >
            <Text style={styles.forgotPasswordText}>Forgot Password?</Text>
          </TouchableOpacity>
        </View>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
  },
  content: {
    flex: 1,
    padding: 20,
    justifyContent: 'center',
  },
  header: {
    marginBottom: 40,
    alignItems: 'center',
  },
  title: {
    fontSize: 32,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 8,
  },
  subtitle: {
    fontSize: 16,
    color: '#666',
    textAlign: 'center',
  },
  form: {
